import{_ as t,o as r,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-10-30（AI 系统架构 · LLM 自主科学发现 / 优化器 / 群体决策记忆 / 潜世界模型 / 实时智能体）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-30-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-30-ai.md"}'),i={name:"topics/ai-system-architecture/science-daily-2026-10-30-ai.md"};function g(e,o,l,a,c,d){return r(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-30-ai-系统架构-·-llm-自主科学发现-优化器-群体决策记忆-潜世界模型-实时智能体" tabindex="-1">科学日报 · 2026-10-30（AI 系统架构 · LLM 自主科学发现 / 优化器 / 群体决策记忆 / 潜世界模型 / 实时智能体） <a class="header-anchor" href="#科学日报-·-2026-10-30-ai-系统架构-·-llm-自主科学发现-优化器-群体决策记忆-潜世界模型-实时智能体" aria-label="Permalink to &quot;科学日报 · 2026-10-30（AI 系统架构 · LLM 自主科学发现 / 优化器 / 群体决策记忆 / 潜世界模型 / 实时智能体）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> — 第49期 ｜ AI 板块（5 篇） 落盘说明：文件名带 <code>-ai</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-30-ai-·-1-5-llm-能否在「物理定律被改写」的世界里自主发现异常、找到规律" tabindex="-1">科学日报 2026-10-30（AI · 1/5）：LLM 能否在「物理定律被改写」的世界里自主发现异常、找到规律？ <a class="header-anchor" href="#科学日报-2026-10-30-ai-·-1-5-llm-能否在「物理定律被改写」的世界里自主发现异常、找到规律" aria-label="Permalink to &quot;科学日报 2026-10-30（AI · 1/5）：LLM 能否在「物理定律被改写」的世界里自主发现异常、找到规律？&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> ｜ arXiv: 2610.37649</p></blockquote><ul><li>问题：科学发现常始于「<strong>出乎意料的观察</strong>」。但若<strong>世界本身的物理定律被改写了</strong>（如重物反而落得更慢），LLM 能否<strong>没人告诉它该研究什么</strong>，就<strong>自己注意到异常、并通过实验找出规律</strong>？</li><li>方法：<strong>LongChang</strong> 自动化框架——生成<strong>物理定律被改写</strong>的模拟世界（一条或多条定律偏离常理）；LLM 充当<strong>探索者</strong>，<strong>操纵物体、制造工具</strong>去追问自己提出的问题，<strong>不给定研究任务、不给关于定律的提示</strong>；另有独立 LLM 智能体负责<strong>生成/审阅场景、审阅工具设计、并按改写的物理定律与探索记录评估报告的正确性与实验支持度</strong>；这些记录又<strong>指导场景演化</strong>，使整个循环<strong>无需人工介入（人不在环上）</strong>。</li><li>结果（实测）： <ul><li>12 个 LLM 中，<strong>仅 GPT-6-Astra 达到 16.7% 的发现率</strong>，<strong>其余 11 个均为 0%</strong>；</li><li>探索记录显示存在<strong>未被追查的异常</strong>，且对改写定律<strong>只能部分识别</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「自由探索 ≠ 会做科学」</strong> —— 即使有工具、有自由、有自动评审，<strong>11/12 模型发现率为 0</strong>。判据：<strong>当任务要求「在无明确目标下识别反常并主动追查」时，当前 LLM 的能力远低于其在有题面任务上的表现</strong>——这是与 10-09「研究型 Agent 需自己凝结问题」同一条缺口。</li><li><strong>「把环境定律当可控变量」</strong> —— 改写物理定律、并让场景随探索记录演化，本质是<strong>用环境生成器把『未知』变成可扫描的轴</strong>。判据：<strong>要测「自主发现」能力，先造一个定律可改、且会随你的探索变化的世界</strong>，而非固定题库。</li><li><strong>一句话定位</strong>：与 10-29「无标签 RLVR 群体崩塌」「工具使用缩放律」同属<strong>把智能体放到开放、可自演化的环境里量能力</strong>这条 <code>ai-system-architecture</code> 主线。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-30-ai-·-2-5-muongs——用-gram–schmidt-只扣掉「径向分量」-放松权重范数控制" tabindex="-1">科学日报 2026-10-30（AI · 2/5）：MuonGS——用 Gram–Schmidt 只扣掉「径向分量」，放松权重范数控制 <a class="header-anchor" href="#科学日报-2026-10-30-ai-·-2-5-muongs——用-gram–schmidt-只扣掉「径向分量」-放松权重范数控制" aria-label="Permalink to &quot;科学日报 2026-10-30（AI · 2/5）：MuonGS——用 Gram–Schmidt 只扣掉「径向分量」，放松权重范数控制&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> ｜ arXiv: 2610.37647</p></blockquote><ul><li>问题：权重衰减与显式范数约束能改善预训练优化，但「<strong>为何有效、需要多少</strong>」缺乏统一理解。</li><li>方法：用<strong>累积有效学习率 C_T = Σ_{t&lt;T} η_t/‖W_t‖_F</strong> 分析 Muon 的范数控制——在更新方向有界时，任意区间上的<strong>累积给出相对权重位移的上界</strong>。在此视角下提出 <strong>MuonGS</strong>：用 <strong>Gram–Schmidt 投影去掉每次 Muon 更新的径向分量，但不固定权重范数</strong>。</li><li>结果（实测）： <ul><li>理论：<strong>原始 Muon 只能对数式累积</strong>（可能限制探索）；<strong>MuonW / MuonH 至少保证线性累积</strong>；MuonGS 可证 <strong>‖W‖ 至多 ∝√t</strong>，故 <strong>C_T = Ω(√T)</strong>，对<strong>光滑尺度不变目标</strong>还给出 <strong>O(T^{−1/2}) 的平稳性保证</strong>；</li><li>实证：<strong>160M / 400M 稠密模型</strong> + <strong>135M 激活、1B 总量 MoE</strong> 上，长训练期 MuonGS 验证困惑度<strong>低于 MuonH</strong>；稠密模型在<strong>匹配验证损失</strong>下取得<strong>约 15% 等效 token 加速</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>physics</code> 的「守恒/不变量的显式控制」）： <ol><li><strong>「用一个可证的标量，替代一堆经验超参」</strong> —— 把「范数控制该多强」统一到<strong>累积有效学习率 C_T</strong> 这一个量：<strong>要什么规模的权重位移，就能算出需要多少累积</strong>。判据：<strong>当调参凭经验时，先找那个「积分类的守恒量」，让超参有可证的几何意义。</strong></li><li><strong>「放松约束 &gt; 硬约束」</strong> —— 不固定范数、只去掉径向分量，反而让范数能<strong>慢速（∝√t）增长</strong>、<strong>保留探索空间</strong>，长程上优于强行锁范数的 MuonH。判据：<strong>当硬约束让优化器磨掉后期进展时，改成「控制增长率」而非「锁死数值」。</strong> 这与外脑「改路径/换通道优于加力度」同族。</li><li><strong>一句话定位</strong>：把 <code>ai-system-architecture</code> 的优化器分支从 10-29「无标签 RLVR 崩塌」补上<strong>预训练优化器的范数控制理论</strong>。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-30-ai-·-3-5-把「群体讨论」压成一段记忆时-为什么「取最稀有」和「取最相关」都失灵" tabindex="-1">科学日报 2026-10-30（AI · 3/5）：把「群体讨论」压成一段记忆时，为什么「取最稀有」和「取最相关」都失灵 <a class="header-anchor" href="#科学日报-2026-10-30-ai-·-3-5-把「群体讨论」压成一段记忆时-为什么「取最稀有」和「取最相关」都失灵" aria-label="Permalink to &quot;科学日报 2026-10-30（AI · 3/5）：把「群体讨论」压成一段记忆时，为什么「取最稀有」和「取最相关」都失灵&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> ｜ arXiv: 2610.37624</p></blockquote><ul><li>问题：当一个 <strong>LLM 群体</strong>的讨论要被压缩成<strong>短记忆</strong>交给最终决策者时，<strong>记忆该保留什么</strong>？两条自然启发式：保留<strong>最稀有的主张</strong>，或保留<strong>与决策标准最相关的主张</strong>。</li><li>方法：提出 <strong>CrossProfile</strong> 诊断基准——<strong>60 个模板、自动校验答案键</strong>，在<strong>文本固定不变</strong>下<strong>交叉改变支持性/诱饵性/无关事实的归属</strong>（共 <strong>480 个任务</strong>），覆盖 Qwen2.5-7B、Llama-3.1-8B 与两个 DeepSeek。</li><li>结果（实测）： <ul><li><strong>按相关性筛选会把诱饵重新放进来</strong>（诱饵本就在题上）——即便用<strong>完美相关性过滤器</strong>，在经典隐藏剖面配置下也<strong>比「最稀有优先」低 23–31 分</strong>；</li><li><strong>最稀有优先平均并不优于随机</strong>，只在「稀有事实恰好有用」时才赢；</li><li>准确率<strong>跟随记忆保留的「证据平衡」，而非选取策略</strong>；</li><li>决策模型叠加<strong>社会认同</strong>效应：<strong>对「被多数智能体署名」的事实赋额外权重</strong>——<strong>去掉署名标签、或固定行序下随机重排署名</strong>，准确率<strong>升 13–24 分</strong>；</li><li>更意外：自然讨论中<strong>证据在记忆起作用之前就已丢失——完整转录本准确率反而低于「完全无笔记」</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code> §「聚合而非相加」）： <ol><li><strong>「压缩的稳定性取决于『保留了什么平衡』，而非『按什么规则挑』」</strong> —— 两条看似合理的选择规则都失败，决定成败的是<strong>记忆里各方向证据的相对权重</strong>。判据：<strong>做多智能体/多源聚合时，先检查「压缩后各类证据是否还平衡」，而不是纠结用哪条挑选启发式。</strong></li><li><strong>「元数据（谁说的）会劫持判断」</strong> —— 「多数署名」触发<strong>社会认同偏差</strong>，<strong>删掉/打乱是哪来的</strong>反而更准。判据：<strong>当聚合结论失真时，先试着拿掉『来源/多数』这类社会性标签，看结论是否回正。</strong></li><li><strong>一句话定位</strong>：给 <code>ai-system-architecture</code> 的「多智能体聚合」补一条<strong>实证反例</strong>：<strong>更多信息（完整转录本）不等于更好决策</strong>——与 10-29「集体崩塌」「工具缩放律」同族，都在拆「群体/规模一定更好」的直觉。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-30-ai-·-4-5-潜空间世界模型「并不真的建模环境动力学」——等价性判据-lrc-指标" tabindex="-1">科学日报 2026-10-30（AI · 4/5）：潜空间世界模型「并不真的建模环境动力学」——等价性判据 + LRC 指标 <a class="header-anchor" href="#科学日报-2026-10-30-ai-·-4-5-潜空间世界模型「并不真的建模环境动力学」——等价性判据-lrc-指标" aria-label="Permalink to &quot;科学日报 2026-10-30（AI · 4/5）：潜空间世界模型「并不真的建模环境动力学」——等价性判据 + LRC 指标&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> ｜ arXiv: 2610.37588</p></blockquote><ul><li>问题：<strong>世界模型</strong>被广泛提议为让智能体在长时间/空间尺度上推理的核心组件，但评测多强调<strong>任务表现</strong>，很少回答「学到的世界模型是否真的学到了反映环境结构的<strong>预测性潜动力学</strong>」。</li><li>方法：提出「<strong>忠实潜世界模型（faithful latent world model）</strong>」——把它定义为<strong>环境的转移映射</strong>与<strong>学到的潜动力学</strong>之间的<strong>等变（equivariance）条件</strong>；并提出 <strong>潜轨迹一致性（latent rollout consistency, LRC）</strong>，作为评估<strong>动作条件潜预测</strong>的指标。</li><li>结果（实测）：在所研究的<strong>全部当前最先进潜世界模型</strong>中，<strong>没有一个是通过真正忠实地建模环境动力学来解任务的</strong>（原文称 this is striking）——即<strong>任务分数高不蕴含动力学建模忠实</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>physics</code> 的「不变量/等变」）： <ol><li><strong>「高分 ≠ 学到了机制」</strong> —— 与 10-29 Wilson 环注意力「<strong>名义上非线性、实测复现出线性交互</strong>」同族：<strong>任务指标会被「捷径解」满足，必须单独检验机制是否被忠实学到。</strong> 判据：<strong>当你关心的是「模型是否理解了机制」时，任务分数是必要不充分证据，要补一条机制层面的一致性指标（如 LRC）。</strong></li><li><strong>「把『忠实』定义成一条可检验的等变关系」</strong> —— 把模糊的「世界模型是否对」<strong>降维成「环境转移图与潜动力学是否等变」</strong>。判据：<strong>当「理解/忠实」这类词无法检验时，找一个它与真实系统的等变/交换律，把它变成可测的等式。</strong></li><li><strong>一句话定位</strong>：给 <code>ai-system-architecture</code> 的「世界模型/潜空间推理」主线一条<strong>否证性结论</strong>：SOTA 潜世界模型当前<strong>不靠忠实动力学求解</strong>。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-30-ai-·-5-5-实时交互的-vlm-智能体——环境一暂停-成功率从-9-跳到-75" tabindex="-1">科学日报 2026-10-30（AI · 5/5）：实时交互的 VLM 智能体——环境一暂停，成功率从 9% 跳到 75% <a class="header-anchor" href="#科学日报-2026-10-30-ai-·-5-5-实时交互的-vlm-智能体——环境一暂停-成功率从-9-跳到-75" aria-label="Permalink to &quot;科学日报 2026-10-30（AI · 5/5）：实时交互的 VLM 智能体——环境一暂停，成功率从 9% 跳到 75%&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> ｜ arXiv: 2610.37567</p></blockquote><ul><li>问题：AI 智能体在<strong>有充裕思考时间</strong>的领域（数学、软件工程、桌面应用）进步显著；但在<strong>要求实时交互</strong>的场景（玩游戏、操作物理设备）表现如何并不清楚——这类场景中<strong>环境状态会在智能体推理、甚至一次前向传播的过程中继续演化</strong>。</li><li>方法：<strong>Gym-Anything-RT</strong>——用<strong>智能体流水线</strong>自动生成<strong>视觉小游戏</strong>，覆盖<strong>实时交互的六项能力分类学</strong>（含感知环境、在演化状态下行动等）；关键设计是<strong>同一小游戏既能实时运行、也能暂停或放慢环境</strong>，从而<strong>受控对比「实时 vs 有思考时间」</strong>。</li><li>结果（实测）： <ul><li><strong>GPT-6 Astra（xHigh）实时通过率仅 9.0%</strong>，而<strong>环境暂停后升至 75.0%</strong>（巨大实时交互缺口）；</li><li>前沿智能体的有趣行为：<strong>被赋予写代码能力时，它们会写出「绕过实时感知与行动需求」的代码</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「实时性是一个独立的、此前被掩盖的能力轴」</strong> —— 把环境一暂停，同一个模型从 9% 跳到 75%，说明<strong>当前基准把「实时决策」这一轴隐藏了</strong>。判据：<strong>当评测允许「停下想清楚」，你测的其实是带停顿的能力；要量真实交互能力，必须让环境在推理期间继续跑。</strong></li><li><strong>「能力会被『绕过』——找到捷径就不做真本事」</strong> —— 给写码能力后，模型<strong>写代码绕开实时感知与行动</strong>。判据：<strong>当一个能力可由更强的旁路能力替代时，模型会走旁路</strong>，所以「允许写码」的基准测不出实时交互。这与 10-29「GRPO 预算化强验证器审计——压制作弊」同族：<strong>先堵旁路，再量能力。</strong></li><li><strong>一句话定位</strong>：把 <code>ai-system-architecture</code> 的智能体评测从「静态任务成功率」扩到**「实时性」这一新轴**，并与 10-29「EBench 前沿智能体画像」互补。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ <code>topics/ai-brain/index.md</code> ｜ 第49期 AI 板块</p></blockquote><p>关键词：科学日报第49期、LLM 自主科学发现、LongChang、改写物理定律、自由探索、异常识别、GPT-6-Astra 16.7%、无人在环、工具使用、MuonGS、Muon 优化器、Gram-Schmidt、径向分量、权重范数控制、累积有效学习率 C_T、Omega(sqrtT)、O(T^-1/2) 平稳性、尺度不变目标、MoE 135M/1B、15% 等效 token 加速、CrossProfile、隐藏剖面 hidden profile、群体决策记忆压缩、最稀有优先、相关性过滤、诱饵 decoy、证据平衡、社会认同偏差、署名标签、完整转录本反而更差、潜世界模型 latent world model、忠实 faithful、等变 equivariance、潜轨迹一致性 LRC、动作条件潜预测、Gym-Anything-RT、实时交互、VLM 智能体、100 实时小游戏、暂停环境 9%→75%、写代码绕过实时感知、六项能力分类学、实时性作为独立能力轴、堵旁路再量能力</p><p>关联：<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-29-ai.md</code>（ThinkWorld / 规范注意力 / 工具缩放律 / HoS / 无标签 RLVR 崩塌）、<code>topics/ai-brain/index.md</code>、<code>topics/ai-brain/auto-link-quality-fixes.md</code>、<code>topics/physics/index.md</code>（不变量/等变）、<code>topics/materials/index.md</code></p>',26)])])}const m=t(i,[["render",g]]);export{h as __pageData,m as default};
